function d_threat_score(P,R){var iocs=P.iocs||[];var rows=iocs.map(function(o){var score=o.severity*(o.confidence||0.5)*(o.recent?1.5:1);return{ioc:o.value,score:+score.toFixed(2),action:score>2?'block':score>1?'monitor':'log'};});rows.sort(function(a,b){return b.score-a.score;});return{ranked:rows,highest:rows.length?rows[0].ioc:null};}

